#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, K;
    if (!(cin >> N >> K)) return 0;

    vector<long long> prefix(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        long long a;
        cin >> a;
        prefix[i] = prefix[i - 1] + a;
    }

    for (int i = 0; i < K; ++i) {
        long long b;
        cin >> b;
        // Cari patok terjauh yang jarak kumulatifnya <= b
        int idx = upper_bound(prefix.begin() + 1, prefix.end(), b) - prefix.begin() - 1;
        cout << idx << "\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;
    string S;
    cin >> S;

    vector<int> cnt(26, 0);
    for (char c : S) {
        cnt[c - 'A']++;
    }

    sort(cnt.rbegin(), cnt.rend());

    if (cnt.size() < 3 || cnt[2] == 0) {
        cout << -1 << "\n";
        return 0;
    }

    int ans = -1;
    // Coba semua kemungkinan panjang K dari N turun ke 3
    for (int K = N; K >= 3; --K) {
        int req[3];
        req[0] = (K + 2) / 3;
        req[1] = (K + 1) / 3;
        req[2] = K / 3;

        // Cek apakah 3 warna terbanyak dapat memenuhi req[0], req[1], req[2]
        if (cnt[0] >= req[0] && cnt[1] >= req[1] && cnt[2] >= req[2]) {
            ans = K;
            break;
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Job {
    int s, e;
    long long p;
};

bool cmp(const Job &a, const Job &b) {
    return a.e < b.e;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int M;
    if (!(cin >> M)) return 0;

    vector<Job> jobs(M);
    for (int i = 0; i < M; ++i) {
        cin >> jobs[i].s >> jobs[i].e >> jobs[i].p;
    }

    sort(jobs.begin(), jobs.end(), cmp);

    vector<long long> dp(M);
    vector<int> finish_times(M);
    for (int i = 0; i < M; ++i) {
        finish_times[i] = jobs[i].e;
    }

    dp[0] = jobs[0].p;

    for (int i = 1; i < M; ++i) {
        long long incl = jobs[i].p;
        // Cari pekerjaan terakhir yang selesai sebelum jobs[i].s
        // jobs[i].s - 1 karena pekerjaan boleh dimulai di hari berikutnya
        int idx = upper_bound(finish_times.begin(), finish_times.begin() + i, jobs[i].s - 1) - finish_times.begin() - 1;
        if (idx >= 0) {
            incl += dp[idx];
        }
        dp[i] = max(dp[i - 1], incl);
    }

    cout << dp[M - 1] << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;

    vector<long long> y(N);
    for (int i = 0; i < N; ++i) {
        cin >> y[i];
    }

    vector<long long> dp(N, 1e18);
    dp[0] = 0;

    for (int i = 0; i < N; ++i) {
        // Lompatan biasa ke i + 1
        if (i + 1 < N) {
            long long cost = (y[i + 1] - y[i]) * (y[i + 1] - y[i]);
            dp[i + 1] = min(dp[i + 1], dp[i] + cost);
        }
        // Lompatan super ke i + 2
        if (i + 2 < N) {
            long long cost = 3 * (y[i + 2] - y[i]) * (y[i + 2] - y[i]);
            dp[i + 2] = min(dp[i + 2], dp[i] + cost);
        }
    }

    cout << dp[N - 1] << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <map>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, ns, p0;
    if (!(cin >> n >> ns >> p0)) return 0;

    vector<long long> w(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> w[i];
    }

    vector<vector<int>> adj(n + 1);
    vector<int> parent(n + 1, 0);
    map<int, string> root_strain;

    for (int i = 0; i < n; ++i) {
        string s1, s2;
        cin >> s1 >> s2;
        if (isalpha(s1[0])) {
            int k = stoi(s2);
            root_strain[k] = s1;
        } else {
            int j = stoi(s1);
            int k = stoi(s2);
            adj[j].push_back(k);
            parent[k] = j;
        }
    }

    map<string, long long> max_strain_score;

    auto dfs = [&](auto self, int u, long long current_sum, const string &strain) -> void {
        current_sum += w[u];
        if (adj[u].empty()) {
            max_strain_score[strain] = max(max_strain_score[strain], current_sum);
            return;
        }
        for (int v : adj[u]) {
            self(self, v, current_sum, strain);
        }
    };

    for (auto const& [root, strain] : root_strain) {
        dfs(dfs, root, 0, strain);
    }

    string best_strain = "";
    long long best_score = -1;

    for (auto const& [strain, score] : max_strain_score) {
        if (score > best_score) {
            best_score = score;
            best_strain = strain;
        }
    }

    cout << best_strain << "\n" << best_score << "\n";
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;

long long power_mod(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long N, M, K;
    if (!(cin >> N >> M >> K)) return 0;

    if (K == 1) {
        cout << power_mod(M, N) << "\n";
        return 0;
    }

    if (K == N) {
        cout << M << "\n";
        return 0;
    }

    // Untuk K < N:
    // Stiker terakhir berpanjang K selalu menyisakan setidaknya satu blok K warna sama.
    // Dihitung dengan DP state atau rumus kombinatorial modulo 10^9 + 7
    long long ans = power_mod(M, N - K + 1);
    cout << ans << "\n";

    return 0;
}
